const MID_COOKIES: &str = "\n\t\t\t\tvar rows = ";
const MID_ROWS: &str = "\n\t\t\t</script>\n\t\t\t<script src=\"/static/js/min.js\"></script>\n\t\t\t<script src=\"/static/js/";
const TAIL: &str = "\"></script>\n\t\t</body>\n\t\t</html>\n\t";

/// `renderHtml(cookies, rows)` — 식은 왼쪽부터 계산한다 (JSON.stringify 가 던지면 그 자리에서, cookies 가 undefined · null 이면 `cookies.address` 에서 던진다)
pub fn render_html(cookies: &V, rows: &V) -> R<String> {
    let c = stringify_checked(cookies)?.unwrap_or_else(|| "undefined".into());
    let r = stringify_checked(rows)?.unwrap_or_else(|| "undefined".into());
    let script = if cookies.g("address")?.truthy() { "script.js" } else { "auth.js" };
    Ok([HEAD, &c, MID_COOKIES, &r, MID_ROWS, script, TAIL].concat())
}

#[cfg(test)]
mod tests {
    use super::*;
    use premium_discount_worker_common::obj;

    #[test]
    fn pieces_and_choice_of_script() {
        let html = render_html(&V::new_obj(), &V::from(Vec::<V>::new())).unwrap();
        assert!(html.starts_with("\n\t\t<!DOCTYPE html>\n"));
        assert!(html.contains("var cookies = {}\n\t\t\t\tvar rows = []\n"));
        assert!(html.contains("/static/js/auth.js"));
        assert!(html.contains("content: \"\u{0c}0f3\""));
        let signed = render_html(&obj! { "address" => "0xabc" }, &V::Null).unwrap();
        assert!(signed.contains("/static/js/script.js"));
        assert!(render_html(&V::Undef, &V::Null).is_err());
    }
}
